scripts.script:
// Shared by the vanilla-js, React and Vue builds: the data behind all five
// cards and the wiring for each. Every card holds one live chart and every
// button only ever calls updateOptions, so what you are watching is the morph
// engine rather than a rebuild.
//
// Between them the cards cover every type the engine can morph:
//   bar family      bar, funnel, pyramid, histogram
//   radial family   pie, donut, polarArea, radialBar (and gauge, which is the
//                   same renderer with a different sweep)
//   unit family     unit, waffle
//   summary family  boxPlot, violin
//   partition       treemap, sunburst
// The morph speed slider at the top drives all five at once.

var MORPH_SPEED = 700

// Deterministic noise, so the page looks the same on every load.
function seededRandom(seed) {
  var s = seed
  return function () {
    s = (s * 16807) % 2147483647
    return (s - 1) / 2147483646
  }
}

// One standard normal draw, Box-Muller.
function gauss(rand) {
  return (
    Math.sqrt(-2 * Math.log(Math.max(rand(), 1e-9))) *
    Math.cos(2 * Math.PI * rand())
  )
}

function markActive(scope, attr, value) {
  var buttons = [].slice.call(document.querySelectorAll(scope + ' [' + attr + ']'))
  buttons.forEach(function (b) {
    b.className = b.getAttribute(attr) === value ? 'on' : ''
  })
}

function setReadout(id, html) {
  var el = document.querySelector(id)
  if (el) el.innerHTML = html
}

// ---------------------------------------------------------------------------
// Cards 1 and 2: one week of orders, by channel.
// ---------------------------------------------------------------------------
var CHANNELS = ['Direct', 'Search', 'Referral', 'Social', 'Email']

// Kept in descending order on purpose. A funnel and a pyramid are only
// truthful when the stages fall, so no view has to re-sort, which means a
// channel keeps its rank, its colour and its place through every shape: pick
// one and you can follow it across every button.
var ORDERS = [55, 44, 41, 33, 27]

// One dot per this many orders. Two keeps a cluster readable while giving the
// morph enough grain to work with: a bar coming apart into ~25 fine pieces
// reads as dissolving, into 8 large ones as breaking.
var ORDERS_PER_DOT = 2

// A radialBar is a full ring per channel. Passed explicitly on every switch:
// the previous render's angles are already merged into the live config, so
// leaving them out would inherit whatever the last radial view used.
var FULL_RING = {
  startAngle: 0,
  endAngle: 360,
  inverseOrder: true,
  hollow: { size: '8%' },
  track: { show: false },
}

var RADIAL_SHAPES = ['pie', 'donut', 'polarArea', 'radialBar']

function isRadialShape(shape) {
  return RADIAL_SHAPES.indexOf(shape) > -1
}

function shapeSeries(shape, values) {
  // The radial family reads a flat list of numbers, the bar family the usual
  // series envelope. Nothing else differs: the mapping is positional, so mark
  // number three is mark number three in every one of these shapes.
  return isRadialShape(shape)
    ? values.slice()
    : [{ name: 'Orders', data: values.slice() }]
}

function shapeOptions(shape, values) {
  var opts = {
    chart: { type: shape === 'column' ? 'bar' : shape },
    labels: CHANNELS,
    series: shapeSeries(shape, values),
  }
  if (shape === 'column') {
    opts.plotOptions = { bar: { horizontal: false } }
  } else if (shape === 'bar') {
    opts.plotOptions = { bar: { horizontal: true } }
  } else if (shape === 'radialBar') {
    opts.plotOptions = { radialBar: FULL_RING }
  }
  return opts
}

// Card 1: nine shapes over the same five numbers. It opens on the polar area
// rather than the column so the page does not begin with two identical bar
// charts; every button is one updateOptions away from any other.
function wireShapes(chart) {
  var shape = 'polarArea'
  var values = ORDERS.slice()

  markActive('#card-shapes', 'data-shape', shape)

  ;[].slice
    .call(document.querySelectorAll('#card-shapes [data-shape]'))
    .forEach(function (btn) {
      btn.addEventListener('click', function () {
        var next = btn.getAttribute('data-shape')
        if (next === shape) return
        shape = next
        markActive('#card-shapes', 'data-shape', shape)
        chart.updateOptions(shapeOptions(shape, values))
      })
    })

  var shuffle = document.querySelector('#shuffle-orders')
  if (shuffle) {
    shuffle.addEventListener('click', function () {
      // Still descending, so the funnel and the pyramid stay honest. This one
      // is not a type change at all: same marks, new numbers, which is the
      // ordinary update animation rather than the morph.
      values = []
      for (var i = 0; i < CHANNELS.length; i++) {
        values.push(20 + Math.floor(Math.random() * 50))
      }
      values.sort(function (a, b) {
        return b - a
      })
      chart.updateSeries(shapeSeries(shape, values))
    })
  }
}

// Card 2: the same week as objects. One dot per two orders.
function unitSeries(values) {
  return values.map(function (v, i) {
    var n = Math.max(1, Math.round(v / ORDERS_PER_DOT))
    var data = []
    for (var k = 0; k < n; k++) {
      data.push({ id: CHANNELS[i] + '-' + k, name: CHANNELS[i] })
    }
    return { name: CHANNELS[i], data: data }
  })
}

var DOT_LAYOUT = {
  // One column of dots per channel, so a cluster stands where its bar did.
  layout: 'columns',
  shape: 'circle',
  size: 6,
  // Keep a dot's identity across every regroup, so the same object leaves and
  // returns to the same place on a round trip.
  transition: 'identity',
  // Off because they would be the only text on this card, and they arrive at
  // their final places while the pieces are still in the air.
  clusterLabels: { show: false },
}
var WAFFLE_LAYOUT = {
  layout: 'grid',
  shape: 'square',
  size: 9,
  transition: 'identity',
  clusterLabels: { show: false },
}

function isUnitView(view) {
  return view === 'dots' || view === 'waffle'
}

function wireCounted(chart) {
  var view = 'column'
  var values = ORDERS.slice()
  var total = values.reduce(function (a, b) {
    return a + b
  }, 0)
  var dots = unitSeries(values).reduce(function (n, c) {
    return n + c.data.length
  }, 0)

  var COPY = {
    column: 'Five marks, each standing for the orders it counted.',
    pie: 'The same five marks, now sharing one circle.',
    donut:
      'A ring, which is the interesting one: the cells follow the ink, so the ' +
      'hole in the middle stays a hole.',
    dots:
      '' + dots + ' dots, one per ' + ORDERS_PER_DOT + ' of the ' +
      '' + total + ' orders. Every dot left from the part of the mark ' +
      'that was counting it.',
    waffle:
      'The same ' + dots + ' objects in one lattice: a waffle is the ' +
      'unit chart laid out on a grid, so this hop is a re-layout, not a type ' +
      'change.',
  }

  function apply(next) {
    var wasUnit = isUnitView(view)
    view = next
    markActive('#card-counted', 'data-count', view)
    setReadout('#counted-readout', COPY[view])

    if (wasUnit && isUnitView(view)) {
      // Both states are the unit renderer, so there is no type to change:
      // updating the layout alone lets the objects keep their identity and
      // walk to their new slots instead of fading through a rebuild.
      chart.updateOptions({
        plotOptions: { unit: view === 'waffle' ? WAFFLE_LAYOUT : DOT_LAYOUT },
      })
      return
    }

    if (isUnitView(view)) {
      chart.updateOptions({
        chart: { type: view === 'waffle' ? 'waffle' : 'unit' },
        series: unitSeries(values),
        plotOptions: { unit: view === 'waffle' ? WAFFLE_LAYOUT : DOT_LAYOUT },
        labels: CHANNELS,
      })
      return
    }

    var radial = view === 'pie' || view === 'donut'
    chart.updateOptions({
      chart: { type: radial ? view : 'bar' },
      series: radial ? values.slice() : [{ name: 'Orders', data: values.slice() }],
      plotOptions: { bar: { horizontal: false } },
      labels: CHANNELS,
    })
  }

  markActive('#card-counted', 'data-count', view)
  setReadout('#counted-readout', COPY[view])
  ;[].slice
    .call(document.querySelectorAll('#card-counted [data-count]'))
    .forEach(function (btn) {
      btn.addEventListener('click', function () {
        var next = btn.getAttribute('data-count')
        if (next !== view) apply(next)
      })
    })
}

// ---------------------------------------------------------------------------
// Card 3: how long a parcel took, by shipping tier. Three samples, three
// summaries of them, and the readings themselves.
// ---------------------------------------------------------------------------
var TIERS = (function () {
  var rand = seededRandom(20260814)
  function draw(n, make) {
    var out = []
    while (out.length < n) {
      var v = make()
      if (v > 0.2 && v < 11) out.push(Math.round(v * 10) / 10)
    }
    return out
  }
  return [
    {
      // Tight and early: an express parcel is boring, which is the point.
      name: 'Express',
      values: draw(52, function () {
        return 1.5 + gauss(rand) * 0.3
      }),
    },
    {
      // Two camps: most parcels catch the daily van, the rest wait for the
      // next one. A box plot cannot show that gap; a violin can.
      name: 'Standard',
      values: draw(52, function () {
        return (rand() < 0.55 ? 2.6 : 4.4) + gauss(rand) * 0.45
      }),
    },
    {
      // Skewed: usually fine, occasionally a week.
      name: 'Economy',
      values: draw(52, function () {
        return 4.2 - Math.log(Math.max(rand(), 1e-9)) * 1.5
      }),
    },
  ]
})()

var SUMMARY_SERIES = [
  {
    name: 'Days',
    // Raw observations only, in both the box and the violin: the library runs
    // the five-number summary and the density estimate, which is exactly why
    // it can hand the readings back afterwards.
    data: TIERS.map(function (t) {
      return { x: t.name, points: t.values }
    }),
  },
]

var READINGS_LAYOUT = {
  layout: 'scatter',
  unitValue: 1,
  size: 3.5,
  scatter: {
    // Value on Y with one lane per tier across X, matching the summaries. The
    // value-axis keys keep their x* names in either orientation.
    orientation: 'vertical',
    spread: 'jitter',
    xTitle: 'Days in transit',
    // 0 to 11 in whole days. The summary views say tickAmount 11 for the same
    // grid: there it counts intervals, here it counts the labels themselves.
    xMin: 0,
    xMax: 11,
    tickAmount: 12,
  },
}

function wireSample(chart) {
  var view = 'boxPlot'
  var readings = TIERS.reduce(function (n, t) {
    return n + t.values.length
  }, 0)

  var COPY = {
    boxPlot:
      'Five numbers per tier. Three very different samples can share them, ' +
      'which is what the other two views are for.',
    violin:
      'The same three samples as densities: now the two camps inside ' +
      'Standard are visible, and so is the tail on Economy. The ' +
      'box did not disappear, it unfolded, whiskers and all.',
    readings:
      '' + readings + ' parcels, one dot each, handed back by ' +
      'rowSeries(). Every dot left from the mark that summarised it.',
  }

  function apply(next) {
    view = next
    markActive('#card-sample', 'data-summary', view)
    setReadout('#sample-readout', COPY[view])

    if (view === 'readings') {
      // Nothing about the samples is passed back in. The summaries were built
      // from the observations, so the chart can still name the readings behind
      // every mark.
      chart.updateOptions({
        chart: { type: 'unit' },
        series: chart.rowSeries(),
        plotOptions: { unit: READINGS_LAYOUT },
        legend: { show: false },
      })
      return
    }

    chart.updateOptions({
      chart: { type: view },
      series: SUMMARY_SERIES,
      legend: { show: false },
    })
  }

  markActive('#card-sample', 'data-summary', view)
  setReadout('#sample-readout', COPY[view])
  ;[].slice
    .call(document.querySelectorAll('#card-sample [data-summary]'))
    .forEach(function (btn) {
      btn.addEventListener('click', function () {
        var next = btn.getAttribute('data-summary')
        if (next !== view) apply(next)
      })
    })
}

// ---------------------------------------------------------------------------
// Card 4: the pick-and-pack times behind the histogram.
// ---------------------------------------------------------------------------
var DISPATCH = (function () {
  var rand = seededRandom(770423)
  var out = []
  for (var i = 0; i < 420; i++) {
    // Log-normal: a dispatch can run very late but never finish instantly.
    out.push(Math.round(Math.exp(2.95 + gauss(rand) * 0.4)))
  }
  return out
})()
var DISPATCH_SERIES = [{ name: 'Orders', data: DISPATCH }]

// Quick (blue) through typical (teal) to slow (amber, then red), so the blob
// still reads as a distribution once the bars are gone.
var RAMP = ['#4e8cff', '#59c2b0', '#e8c14a', '#ef7d3a', '#d94040']

function rampColor(t) {
  var scaled = Math.max(0, Math.min(1, t)) * (RAMP.length - 1)
  var i = Math.min(RAMP.length - 2, Math.floor(scaled))
  var f = scaled - i
  var a = RAMP[i]
  var b = RAMP[i + 1]
  function mix(o) {
    var av = parseInt(a.substr(o, 2), 16)
    var bv = parseInt(b.substr(o, 2), 16)
    var v = Math.round(av + (bv - av) * f)
    return (v < 16 ? '0' : '') + v.toString(16)
  }
  return '#' + mix(1) + mix(3) + mix(5)
}

function wireBins(chart) {
  var view = 'histogram'

  function apply(next) {
    view = next
    markActive('#card-bins', 'data-bins', view)

    if (view === 'rows') {
      var rows = chart.rowSeries()
      var total = rows.reduce(function (n, c) {
        return n + c.data.length
      }, 0)
      // What comes back is ordinary series data, so it can be decorated.
      rows.forEach(function (cluster, k) {
        var color = rampColor(rows.length > 1 ? k / (rows.length - 1) : 0)
        cluster.data.forEach(function (d) {
          d.fillColor = color
        })
      })
      chart.updateOptions({
        chart: { type: 'unit' },
        series: rows,
        plotOptions: {
          unit: {
            // Not 'columns'. That would stack each bin's dots back into a
            // column the same height and place as the bar they left, so the
            // objects would travel a few pixels and it would look like a
            // redraw. 'packed' gathers them into one blob, which is a journey.
            layout: 'packed',
            unitValue: 1,
            size: 3,
          },
        },
        legend: { show: false },
      })
      setReadout(
        '#bins-readout',
        'One dot per order: ' + total + ' of them, gathered out of ' +
          rows.length + ' bars.',
      )
      return
    }

    chart.updateOptions({
      chart: { type: 'histogram' },
      series: DISPATCH_SERIES,
      legend: { show: false },
    })
    setReadout(
      '#bins-readout',
      'Every bar counts the orders dispatched inside its range.',
    )
  }

  markActive('#card-bins', 'data-bins', view)
  setReadout(
    '#bins-readout',
    'Every bar counts the orders dispatched inside its range.',
  )
  ;[].slice
    .call(document.querySelectorAll('#card-bins [data-bins]'))
    .forEach(function (btn) {
      btn.addEventListener('click', function () {
        var next = btn.getAttribute('data-bins')
        if (next !== view) apply(next)
      })
    })
}

// ---------------------------------------------------------------------------
// Card 5: revenue by category. One partition, two projections of it.
// ---------------------------------------------------------------------------
var CATALOGUE = [
  {
    data: [
      {
        x: 'Apparel',
        y: 88,
        color: '#008FFB',
        children: [
          { x: 'Tops', y: 34, color: '#008FFB' },
          { x: 'Denim', y: 30, color: '#29A1FC' },
          { x: 'Outerwear', y: 24, color: '#52B3FC' },
        ],
      },
      {
        x: 'Home',
        y: 34,
        color: '#00E396',
        children: [
          { x: 'Kitchen', y: 12, color: '#00E396' },
          { x: 'Bedding', y: 10, color: '#29E7A7' },
          { x: 'Decor', y: 12, color: '#52ECB8' },
        ],
      },
      {
        x: 'Outdoor',
        y: 52,
        color: '#FEB019',
        children: [
          { x: 'Camping', y: 26, color: '#FEB019' },
          { x: 'Cycling', y: 15, color: '#FEBD3E' },
          { x: 'Running', y: 11, color: '#FEC963' },
        ],
      },
    ],
  },
]

// The leaves, flattened: a treemap has no hierarchy, so it draws the level the
// two charts share. That is also the level the morph pairs up, tile for arc.
var LEAVES = [
  {
    data: CATALOGUE[0].data.reduce(function (acc, parent) {
      return acc.concat(
        parent.children.map(function (c) {
          return { x: c.x, y: c.y }
        }),
      )
    }, []),
  },
]

// A sunburst colours per node, so its colours travel with the data above. A
// treemap colours from the palette instead, one entry per tile once
// `distributed` is on, so hand it the same colours in the same order.
var LEAF_COLORS = CATALOGUE[0].data.reduce(function (acc, parent) {
  return acc.concat(
    parent.children.map(function (c) {
      return c.color
    }),
  )
}, [])

function wirePartition(chart) {
  var view = 'treemap'

  markActive('#card-partition', 'data-part', view)
  ;[].slice
    .call(document.querySelectorAll('#card-partition [data-part]'))
    .forEach(function (btn) {
      btn.addEventListener('click', function () {
        var next = btn.getAttribute('data-part')
        if (next === view) return
        view = next
        markActive('#card-partition', 'data-part', view)
        chart.updateOptions({
          chart: { type: view },
          series: view === 'sunburst' ? CATALOGUE : LEAVES,
        })
      })
    })
}

// ---------------------------------------------------------------------------
// One slider, five charts.
// ---------------------------------------------------------------------------
function wireSpeed(charts) {
  var input = document.querySelector('#speed')
  var label = document.querySelector('#speed-value')
  if (!input) return
  input.addEventListener('input', function () {
    MORPH_SPEED = parseInt(input.value, 10)
    if (label) label.textContent = MORPH_SPEED
    charts.forEach(function (chart) {
      if (!chart) return
      chart.updateOptions(
        { chart: { animations: { chartTypeMorph: { speed: MORPH_SPEED } } } },
        false,
        false,
      )
    })
  })
}

chart.options:
chart: {
  id: 'morphShapes',
  type: 'polarArea',
  height: 360,
  toolbar: {
    show: false
  },
  animations: {
    enabled: true,
    speed: 800,
    chartTypeMorph: {
      enabled: true,
      speed: 700,
    },
  },
},
grid: {
  show: false
},
labels: CHANNELS,
legend: {
  show: false
},
plotOptions: {
  bar: {
    borderRadius: 4,
    distributed: true,
    barHeight: '99%',
  },
  radialBar: FULL_RING,
  funnel: {
    shape: 'trapezoid',
  },
},
yaxis: {
  show: false,
  axisBorder: {
    show: false,
  }
},
xaxis: {
  labels: {
    show: false
  },
  axisBorder: {
    show: false,
  },
  axisTicks: {
    show: false,
  }
},
dataLabels: {
  enabled: false
},
fill: {
  opacity: 0.9
},
stroke: {
  lineCap: 'butt',
  width: 1,
  colors: ['#fff']
},

chart: {
  id: 'morphCounted',
  type: 'bar',
  height: 360,
  toolbar: {
    show: false
  },
  animations: {
    enabled: true,
    speed: 800,
    chartTypeMorph: {
      enabled: true,
      speed: 700,
    },
  },
},
grid: {
  show: false
},
labels: CHANNELS,
legend: {
  show: false
},
plotOptions: {
  bar: {
    borderRadius: 4,
    distributed: true,
  },
  unit: DOT_LAYOUT,
},
yaxis: {
  show: false,
  axisBorder: {
    show: false,
  }
},
xaxis: {
  labels: {
    show: false
  },
  axisBorder: {
    show: false,
  },
  axisTicks: {
    show: false,
  }
},
dataLabels: {
  enabled: false
},
fill: {
  opacity: 0.9
},
stroke: {
  lineCap: 'butt',
  width: 1,
  colors: ['#fff']
},

chart: {
  id: 'morphSample',
  type: 'boxPlot',
  height: 400,
  toolbar: {
    show: false
  },
  animations: {
    enabled: true,
    chartTypeMorph: {
      enabled: true,
      speed: 700,
    },
  },
},
// Three shades of one hue: the tiers are told apart by their lanes, and a
// single family of colour keeps the box, the violin and the dots recognisably
// the same three groups.
colors: ['#0f9c92', '#12b3a8', '#5ecfc6'],
plotOptions: {
  bar: {
    distributed: true
  },
  boxPlot: {
    colors: {
      upper: '#c8ece9',
      lower: '#9fdcd7'
    },
    points: {
      show: false
    }
  },
  violin: {
    normalize: 'group',
    // The toggle is the reveal here; the built-in overlay would spoil it.
    points: {
      show: false
    }
  },
},
legend: {
  show: false
},
stroke: {
  width: 1,
  colors: ['#8a97a3']
},
yaxis: {
  // The same domain and ticks the readings view pins itself to, so the two
  // states share one grid and the morph never re-scales the room.
  min: 0,
  max: 11,
  tickAmount: 11,
  title: {
    text: 'Days in transit'
  },
},
xaxis: {
  // One explicit label colour keeps the readings view's axis chrome (ticks,
  // title, lane names) on the same near-black as the summary views, instead of
  // the lane names taking the series colour.
  labels: {
    style: {
      colors: '#373d3f'
    }
  }
},

chart: {
  id: 'morphBins',
  type: 'histogram',
  height: 380,
  toolbar: {
    show: false
  },
  animations: {
    enabled: true,
    chartTypeMorph: {
      enabled: true,
      speed: 700,
    },
  },
},
plotOptions: {
  histogram: {
    bins: 20,
  },
},
colors: ['#4e8cff'],
legend: {
  show: false
},
dataLabels: {
  enabled: false
},
xaxis: {
  title: {
    text: 'Minutes from order to dispatch'
  },
  labels: {
    formatter: function (val) {
      return Math.round(val)
    }
  }
},
yaxis: {
  title: {
    text: 'Orders'
  },
},

chart: {
  id: 'morphPartition',
  type: 'treemap',
  height: 420,
  toolbar: {
    show: false
  },
  animations: {
    enabled: true,
    chartTypeMorph: {
      enabled: true,
      speed: 700,
    },
  },
},
colors: LEAF_COLORS,
legend: {
  show: false
},
dataLabels: {
  enabled: true,
  style: {
    fontSize: '12px',
  },
},
plotOptions: {
  treemap: {
    // One palette entry per tile, taken straight from the data above, so a
    // tile and the arc it becomes are the same colour. Shading is off because
    // it would recolour tiles by value and break that pairing.
    distributed: true,
    enableShades: false,
  },
  sunburst: {
    innerSize: '22%',
    borderRadius: 2,
    spacing: 1,
  },
},

react-script:
React.useEffect(() => {
  // The react-apexcharts wrapper owns the render, so reach the live instances
  // by their chart.id, then wire the same five cards the vanilla build does.
  // updateOptions drives each instance directly, so no React state changes and
  // no  is ever re-rendered under it.
  const timer = window.setInterval(() => {
    const shapes = ApexCharts.getChartByID('morphShapes')
    const counted = ApexCharts.getChartByID('morphCounted')
    const sample = ApexCharts.getChartByID('morphSample')
    const bins = ApexCharts.getChartByID('morphBins')
    const partition = ApexCharts.getChartByID('morphPartition')
    if (!shapes || !counted || !sample || !bins || !partition) return
    window.clearInterval(timer)

    wireShapes(shapes)
    wireCounted(counted)
    wireSample(sample)
    wireBins(bins)
    wirePartition(partition)
    wireSpeed([shapes, counted, sample, bins, partition])
  }, 50)

  return () => window.clearInterval(timer)
}, [])

vue-script:
mounted: function () {
  // The vue-apexcharts wrapper owns the render, so reach the live instances by
  // their chart.id, then wire the same five cards the vanilla build does.
  var me = this
  me.morphTimer = window.setInterval(function () {
    var shapes = ApexCharts.getChartByID('morphShapes')
    var counted = ApexCharts.getChartByID('morphCounted')
    var sample = ApexCharts.getChartByID('morphSample')
    var bins = ApexCharts.getChartByID('morphBins')
    var partition = ApexCharts.getChartByID('morphPartition')
    if (!shapes || !counted || !sample || !bins || !partition) return
    window.clearInterval(me.morphTimer)

    wireShapes(shapes)
    wireCounted(counted)
    wireSample(sample)
    wireBins(bins)
    wirePartition(partition)
    wireSpeed([shapes, counted, sample, bins, partition])
  }, 50)
},
beforeDestroy: function () {
  window.clearInterval(this.morphTimer)
},
